svg.script:
//
(function () {
  var svg = document.getElementById('ed-sv');
  if (!svg) return;
  var iT = svg.querySelector('#ed-it');
  var iD = svg.querySelector('#ed-id');

  var DESCS = {
    topview:   ['Top View — Bearing Mount Plate',
                'Plan view: square plate with chamfered corners, central bore, four mounting holes. Scale 2:1. All outer geometry and hole-pattern layout visible here.'],
    frontview: ['Front View — Plate Elevation',
                'Front elevation shows plate thickness, boss profile around bore, and mounting hole depths. Material: ASTM Grade 6 Steel.'],
    sideview:  ['Right Side View',
                'Side elevation confirms boss height and mounting hole alignment with plate body. Used to verify overall assembly clearances.'],
    section:   ['Section A-A — Bore Cross-Section',
                'Cut through plate centre reveals bore geometry: internal shoulder for bearing seating, bore diameter, and clearance fit specification.'],
    notes:     ['Drawing Notes & Title Block',
                'Notes: all dims in mm; ASTM Grade 6 Steel; sharp edges chamfered; anti-corrosion coating on all exposed surfaces. ENGR 220 — AUAD Midterm 2.']
  };

  function reset() {
    svg.querySelectorAll('.e-ring.lit').forEach(function (r) { r.classList.remove('lit'); });
    if (iT) iT.textContent = '';
    if (iD) iD.textContent = 'Hover the highlighted views to explore the bearing mount plate drawing';
  }

  svg.querySelectorAll('.e-feat').forEach(function (g) {
    var id   = g.dataset.id;
    var ring = g.querySelector('.e-ring');
    function on() {
      reset();
      if (ring) ring.classList.add('lit');
      var d = DESCS[id] || ['', ''];
      if (iT) iT.textContent = d[0];
      if (iD) iD.textContent = d[1];
    }
    g.addEventListener('mouseenter', on);
    g.addEventListener('click',      on);
    g.addEventListener('mouseleave', reset);
  });

  svg.addEventListener('click', function (e) {
    if (!e.target.closest('.e-feat')) reset();
  });

  if (window.matchMedia('(prefers-reduced-motion:reduce)').matches) {
    svg.querySelectorAll('.e-ring').forEach(function (r) { r.classList.add('ready'); });
    return;
  }
  svg.querySelectorAll('.e-ring').forEach(function (r, i) {
    setTimeout(function () { r.classList.add('ready'); }, 400 + i * 500);
  });
})();
//
